    RiskDecision,
)


class JsonApprovalStore:
    def __init__(self, path: Path | str):
        self.path = Path(path)

    def create(self, action: Action, risk_decision: RiskDecision) -> ApprovalRequest:
        request = ApprovalRequest(action=action, risk_decision=risk_decision)
        requests = self._load()
        requests.append(request)
        self._save(requests)
        return request

    def get(self, request_id: str) -> ApprovalRequest:
        for request in self._load():
            if request.id == request_id:
                return request
        raise KeyError(request_id)

    def list(self, status: ApprovalStatus | None = None) -> list[ApprovalRequest]:
        requests = self._load()
        if status is None:
            return requests
        return [request for request in requests if request.status == status]

    def resolve(
        self,
        request_id: str,
        status: ApprovalStatus,
        note: str = "",
    ) -> ApprovalRequest:
        if status == ApprovalStatus.PENDING:
            raise ValueError("approval status cannot be pending")
        requests = self._load()
        for index, request in enumerate(requests):
            if request.id != request_id:
                continue
            if request.status != ApprovalStatus.PENDING:
                raise ValueError("approval request is not pending")
            resolved = request.model_copy(
                update={
                    "status": status,
                    "resolved_at": datetime.now(UTC),
                    "resolution_note": note,
                }
            )
            requests[index] = resolved
            self._save(requests)
            return resolved
        raise KeyError(request_id)

    def _load(self) -> list[ApprovalRequest]:
        if not self.path.exists():
            return []
        data = json.loads(self.path.read_text(encoding="utf-8"))
        return [ApprovalRequest.model_validate(item) for item in data]

    def _save(self, requests: list[ApprovalRequest]) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        temporary = self.path.with_suffix(".tmp")
        temporary.write_text(
            json.dumps([request.model_dump(mode="json") for request in requests]),
            encoding="utf-8",
        )
        temporary.replace(self.path)


class ApprovalStateMachine:
    def __init__(self, store: JsonApprovalStore):
        self.store = store

    def approve(self, request_id: str, note: str = "") -> ApprovalRequest:
        return self.store.resolve(request_id, ApprovalStatus.APPROVED, note)

    def reject(self, request_id: str, note: str = "") -> ApprovalRequest:
        return self.store.resolve(request_id, ApprovalStatus.REJECTED, note)

    def expire(self, request_id: str, note: str = "expired") -> ApprovalRequest:
        return self.store.resolve(request_id, ApprovalStatus.EXPIRED, note)

import os

import keyring

from harness.models import CredentialStatus


def mask_secret(value: str) -> str:
    if len(value) > 10:
        return f"{value[:4]}...{value[-4:]}"
    return "*" * len(value)


class CredentialManager:
    def __init__(self, service_name: str = "coding-agent-harness") -> None:
        self.service_name = service_name

    def get_api_key(self, provider: str = "openai") -> str | None:
        return keyring.get_password(self.service_name, provider) or os.getenv("OPENAI_API_KEY")

    def set_api_key(self, api_key: str, provider: str = "openai") -> None:
        keyring.set_password(self.service_name, provider, api_key)

    def clear_api_key(self, provider: str = "openai") -> None:
        keyring.delete_password(self.service_name, provider)

    def status(self, provider: str = "openai") -> CredentialStatus:
        api_key = keyring.get_password(self.service_name, provider)
        if api_key:
            return CredentialStatus(
                provider=provider,
                source="keyring",
                exists=True,
                masked_preview=mask_secret(api_key),
            )

        api_key = os.getenv("OPENAI_API_KEY")
        if api_key:
            return CredentialStatus(
                provider=provider,
                source="env",
                exists=True,
                masked_preview=mask_secret(api_key),
            )

        return CredentialStatus(provider=provider, source="missing", exists=False)

import json
